\u004c\u007c\u0071\u0049\u004d\u006b\u0070\u0024\u0079\u0047\u0054\u0051\u0022\u002c\u004c\u003c\u0021\u0030\u0064\u0060\u006b\u0055\u0079\u0032\u005f\u0034\u0045\u0067\u0039\u006e\u005e\u0045\u0042\u0060\u002b\u0047\u0075\u0021\u0043\u006b\u006f\u0046\u0076\u0041\u0037\u0058\u0069\u007d\u006b\u003b\u0056\u0061\u0028\u006d\u0067\u0024\u0077\u0053\u007b\u0070\u0062\u0029\u0046\u0030\u0065\u002a\u0034\u0045\u003e\u005b\u0053\u007b\u0070\u0062\u0029\u0046\u003d\u0037\u0021\u0060\u005f\u007d\u004b\u007c\u002e\u005b\u0046\u0062\u002a\u0038\u004c\u003e\u0045\u004f\u0053\u002a\u0051\u003d\u006b\u0028\u0040\u0053\u0050\u0074\u0039\u0052\u0040\u0045\u003f\u002a\u0051\u003d\u006b\u0028\u0040\u004c\u005f\u003f\u0021\u006c\u0052\u004e\u004f\u0061\u0051\u0030\u0076\u0045\u0050\u007d\u0030\u007b\u007b\u0054\u0056\u0066\u0058\u0028\u007b\u0072\u0048\u0022\u0037\u006d\u0049\u003b\u0064\u0078\u004c\u006c\u007b\u006b\u003c\u0073\u0057\u0051\u0030\u0076\u0045\u0050\u007d\u0040\u003a\u0049\u003b\u0031\u0036\u0046\u004b\u0074\u0042\u006e\u0047\u0056\u0051\u0035\u002c\u004f\u003b\u0051\u006b\u006b\u0033\u004d\u0057\u0044\u0054\u0070\u0069\u002f\u0029\u004f\u0043\u0021\u0056\u0026\u0021\u0077\u007c\u004e\u0057\u002a\u0042\u0058\u0068\u003b\u0024\u0059\u0076\u0074\u006a\u003c\u0074\u0063\u0063\u0071\u0032\u0023\u0031\u0023\u0039\u0033\u004d\u0056\u006c\u0053\u0059\u0048\u0035\u005a\u0025\u0037\u0049\u0062\u005b\u0033\u0066\u0057\u002c\u005a\u0066\u003f\u0024\u0074\u003b\u006b\u0071\u0069\u0025\u004d\u0055\u0024\u0029\u0034\u0042\u0079\u0031\u0040\u0036\u0030\u0024\u0047\u004f\u002b\u0066\u0057\u002c\u005a\u0078\u002a\u0047\u004a\u0037\u004c\u002e\u0021\u004f\u0026\u002b\u006e\u0052\u0056\u007d\u0059\u004a\u0032\u002f\u003e\u0055\u0059\u006d\u0034\u007d\u0077\u0061\u0060\u003a\u0059\u005a\u0052\u0034\u005a\u0046\u0060\u0049\u002c\u0054\u006b\u0074\u0023\u0069\u0021\u0045\u003d\u0046\u0060\u0031\u0055\u007c\u0023\u0041\u0073\u0021\u002b\u0047\u003c\u0029\u0028\u0056\u0054\u0033\u005d\u0039\u0045\u0029\u0065\u002f\u006f\u006d\u0033\u007d\u0043\u004f\u0078\u0039\u003d\u0060\u0047\u006f\u005e\u0029\u0065\u002f\u005b\u0074\u006a\u003e\u0034\u0022\u0041\u0064\u002e\u0055\u0071\u0022\u0021\u0066\u0045\u0040\u002b\u002c\u0030\u0038\u0043\u007a\u0033\u005b\u0055\u0040\u0046\u0037\u0021\u005e\u002b\u0042\u0043\u0078\u006f\u0047\u0079\u005d\u0049\u0065\u0076\u0038\u003a\u0065\u007c\u0041\u0064\u002c\u006d\u003b\u0076\u002f\u006f\u0051\u0069\u0079\u006b\u0043\u0057\u004f\u0055\u0073\u0025\u0064\u002e\u006b\u0051\u006d\u0034\u0021\u0079\u0048\u005b\u0032\u0044\u002e\u003f\u005a\u0060\u0026\u0055\u007d\u0044\u0048\u0052\u0073\u0071\u004b\u007a\u002f\u0021\u0037\u0065\u0079\u0029\u0078\u006f\u0079\u007d\u0030\u002f\u0070\u003a\u007e\u0035\u0034\u003b\u0053\u0041\u0057\u0065\u0038\u002b\u004f\u0071\u0077\u0023\u0039\u0076\u006e\u0076\u006e\u0042\u0051\u0070\u005d\u0057\u0037\u007d\u002b\u007e\u0046\u0035\u0048\u002c\u006e\u006d\u0062\u002f\u002f\u0054\u0079\u0029\u0078\u006f\u0037\u002c\u0044\u006a\u006d\u004d\u0055\u006d\u0056\u005b\u0078\u0075\u006a\u0023\u0051\u006b\u0047\u0024\u0033\u0056\u002b\u0053\u004d\u002c\u004c\u0047\u0062\u0059\u0059\u0023\u003f\u0070\u0050\u003f\u0029\u002b\u002a\u007c\u0044\u0023\u0052\u0063\u0025\u0065\u002f\u0052\u0079\u003c\u0054\u007a\u0073\u004f\u0056\u0070\u0070\u005a\u0061\u005b\u0052\u0070\u0039\u004a\u002f\u0067\u0060\u0022\u0075\u0077\u007a\u003e\u0075\u0062\u0066\u0056\u0058\u0070\u0044\u004e\u0053\u0068\u0042\u006b\u006e\u003a\u0024\u0052\u006d\u0053\u0036\u004a\u0049\u0068\u0058\u0059\u006a\u0025\u0031\u004e\u004c\u0039\u0038\u0054\u0025\u0072\u0039\u0066\u005e\u0054\u0044\u0073\u004f\u004a\u0047\u0043\u005f\u0023\u0025\u002f\u0039\u006e\u0026\u0026\u0025\u0075\u004a\u0056\u0051\u006e\u003e\u003b\u003f\u003f\u0029\u0036\u003d\u0059\u0057\u006c\u002a\u006d\u003f\u0040\u004f\u0071\u002e\u0046\u0035\u0045\u007e\u0034\u0059\u0031\u0078\u0065\u0035\u0059\u0062\u0039\u0078\u007e\u0064\u0031\u002b\u003e\u004e\u004c\u0037\u003d\u0040\u0031\u007e\u002b\u0076\u002f\u0072\u0023\u0070\u0037\u0023\u0026\u007e\u0059\u007c\u0034\u0042\u002e\u0041\u0021\u0026\u0029\u0029\u0054\u0073\u0078\u0030\u0029\u0057\u004d\u0066\u0077\u006f\u0031\u0023\u0062\u0038\u0069\u005e\u0078\u004c\u005d\u005d\u002a\u006d\u0076\u0069\u002c\u0068\u0028\u0023\u003e\u0067\u0043\u0033\u0071\u0044\u006c\u007b\u0069\u003b\u004c\u0058\u0039\u0063\u002e\u0050\u006c\u0061\u0072\u003f\u0035\u0053\u002b\u0036\u0066\u0078\u007b\u0052\u0058\u0043\u0054\u007b\u0060\u0056\u0072\u0060\u007b\u0052\u0034\u006b\u007c\u0079\u007b\u0077\u0063\u0057\u0070\u0036\u0079\u003c\u006f\u0023\u0039\u0056\u002f\u0036\u007b\u0077\u0063\u0057\u0070\u0036\u0074\u003b\u0066\u005a\u004c\u005a\u0053\u005d\u0062\u0057\u0035\u006a\u0058\u006a\u004c\u0062\u0071\u0042\u0022\u0048\u004a\u0040\u003f\u0056\u0035\u0058\u007d\u004f\u0048\u003c\u005e\u0063\u0040\u0040\u0074\u004b\u0033\u007e\u0066\u003d\u0058\u0076\u0034\u0069\u0023\u0058\u0056\u0060\u004d\u003e\u0049\u004e\u0066\u0039\u0079\u004a\u0043\u003c\u0073\u0045\u0038\u0026\u0078\u0068\u0058\u002e\u003d\u002f\u0048\u0071\u003b\u0068\u0077\u0069\u0049\u0055\u0054\u002e\u0077\u0022\u0068\u0073\u0045\u006c\u0072\u0068\u0061\u0024\u0078\u004d\u005f\u003c\u0022\u004f\u0051\u0024\u003f\u0056\u0048\u005d\u004d\u0072\u0053\u003b\u0058\u0038\u0038\u0022\u0049\u004b\u0024\u0054\u004e\u0025\u0030\u0061\u0022\u005b\u005f\u0028\u0036\u0030\u0061\u007b\u004b\u0048\u0035\u0075\u0075\u0079\u0062\u0054\u0024\u0050\u0074\u0022\u006c\u006c\u0051\u007c\u0048\u007d\u0060\u002b\u006c\u004f\u0028\u0079\u0058\u0067\u0071\u0075\u007c\u007c\u0024\u004d\u0056\u003c\u0060\u004e\u0068\u0047\u004c\u0050\u003c\u0037\u006f\u003f\u003e\u002f\u006d\u0053\u0021\u0022\u006e\u0068\u002e\u005e\u007d\u0070\u0070\u003e\u0022\u0033\u0031\u004d\u005b\u002f\u0039\u004e\u002e\u004e\u0059\u0050\u0063\u0078\u0067\u004b\u0042\u0031\u004e\u003c\u0061\u0049\u0049\u004b\u0059\u0042\u0047\u005f\u0050\u005e\u006d\u0045\u0051\u0065\u002e\u0049\u005b\u005d\u004a\u0038\u0070\u0061\u007b\u005e\u0037\u006a\u006c\u0035\u0042\u0038\u003c\u0062\u0072\u0072\u002a\u0040\u007d\u0074\u0035\u0070\u0056\u0033\u0046\u007a\u0031\u0053\u0024\u0052\u004c\u0051\u006d\u0042\u002b\u0025\u0072\u0072\u002a\u0040\u007d\u0074\u0072\u0034\u0038\u0062\u0060\u003c\u0073\u0061\u0079\u0023\u0060\u0060\u002b\u0067\u006e\u005a\u004b\u0025\u003b\u006f\u002e\u0071\u0060\u0038\u007c\u0022\u007d\u0028\u0051\u0063\u007b\u007d\u0075\u0066\u0073\u0075\u0023\u0068\u0068\u0066\u0036\u0036\u0048\u0068\u004e\u0048\u002e\u0059\u0077\u0023\u007c\u0051\u0063\u0053\u005d\u0075\u0060\u0037\u004d\u0026\u0037\u003b\u0055\u0037\u003a\u0054\u002c\u0067\u0040\u0073\u0063\u002f\u0049\u0028\u0033\u0076\u0033\u0079\u0056\u0026\u0071\u0044\u007e\u002b\u004d\u0040\u004b\u0054\u0043\u0057\u0037\u0025\u0026\u0066\u005a\u0060\u0039\u0022\u0051\u005e\u005e\u007b\u0065\u003d\u0040\u0065\u0026\u0034\u0039\u0022\u0071\u0036\u003e\u0030\u0062\u004a\u0035\u0042\u0061\u004d\u003b\u004c\u0046\u0031\u005e\u005e\u0070\u003e\u007e\u0030\u005e\u0068\u0038\u0044\u0058\u003f\u0079\u0067\u0032\u004b\u0072\u0043\u0024\u0037\u0054\u002c\u006a\u007b\u0068\u0074\u0050\u0047\u005d\u0024\u0034\u0056\u0046\u0066\u003e\u0050\u002f\u0066\u004f\u006e\u0045\u0043\u0049\u0072\u006a\u0036\u007d\u0021\u0045\u0036\u0056\u002c\u003a\u003e\u006e\u0076\u0030\u0041\u0075\u0055\u004a\u005f\u0045\u0076\u0038\u0036\u006d\u0072\u0078\u005a\u0031\u0068\u0073\u0048\u006f\u002a\u0071\u0060\u0058\u005a\u0058\u0034\u0021\u0030\u0030\u0021\u005a\u005b\u0073\u0022\u0067\u0062\u0023\u0023\u0056\u004b\u0067\u0055\u0031\u0023\u0072\u0074\u0042\u0057\u0065\u005e\u0065\u005e\u0050\u0051\u002f\u0068\u003a\u0051\u007a\u0042\u0076\u002c\u002e\u004e\u0062\u004c\u0053\u007c\u0040\u0057\u0042\u0069\u0069\u003b\u0025\u0025\u007c\u0069\u0062\u007c\u0043\u0056\u0073\u003a\u0063\u003d\u0072\u0045\u0022\u0044\u0053\u005d\u002c\u0024\u0037\u003e\u003e\u0048\u0076\u0066\u002b\u0053\u007a\u0051\u0022\u0055\u0055\u006d\u0056\u005b\u0078\u0075\u006a\u0023\u0051\u006b\u0047\u0024\u006c\u0036\u006b\u003c\u0021\u002c\u004c\u0047\u002f\u0068\u0065\u003f\u003e\u0067\u0066\u003d\u0048\u0074\u0023\u0075\u0053\u0038\u0062\u0057\u003d\u0074\u0072\u0059\u0064\u004b\u0043\u0025\u0065\u0045\u004e\u0062\u003f\u0024\u0033\u0065\u0034\u006c\u0052\u007b\u007d\u0070\u0067\u0057\u0037\u0041\u005b\u005b\u0021\u0028\u006c\u0069\u006f\u003a\u0054\u003e\u0064\u0042\u0033\u0028\u0045\u0028\u0028\u0073\u007d\u006e\u0039\u006f\u0023\u002f\u0075\u0051\u002b\u003b\u002f\u0033\u0073\u0060\u007d\u0062\u0039\u0041\u0051\u003d\u005f\u0024\u0057\u0029\u0046\u005e\u0063\u0061\u002a\u007b\u0028\u0042\u005b\u002a\u0070\u004b\u0038\u0058\u0032\u0032\u0030\u0079\u007d\u0074\u0032\u0031\u0061\u002a\u0068\u0035\u0075\u0047\u004e\u0059\u0043\u0075\u0075\u0079\u0049\u0063\u005d\u0043\u003c\u007a\u0056\u0045\u0048\u004d\u0067\u0042\u0044\u0060\u0022\u003d\u0046\u007e\u0032\u0069\u0077\u006c\u003a\u002e\u006d\u006d\u006f\u003d\u0068\u0029\u0060\u0045\u0046\u004c\u0064\u005d\u0054\u0051\u0069\u0036\u0058\u007b\u0045\u006b\u0067\u0045\u003e\u007e\u0047\u0063\u003d\u0070\u0058\u007c\u0023\u0026\u0033\u002c\u004f\u003f\u0045\u0042\u007e\u007e\u0026\u0049\u0076\u0024\u005d\u0021\u0043\u0056\u005b\u0056\u005b\u0062\u0055\u006e\u0066\u004a\u0078\u006d\u0077\u0065\u0029\u004b\u006d\u0038\u0048\u005d\u0021\u0031\u0039\u0024\u0026\u0067\u0075\u0048\u0065\u0032\u0051\u0023\u005b\u006f\u002b\u0075\u007a\u0037\u0064\u005e\u005b\u005a\u0047\u0068\u005d\u0077\u0040\u0063\u0072\u0031\u005e\u0047\u0057\u005f\u0079\u007d\u0050\u007c\u0069\u0025\u006c\u006f\u002e\u003c\u006d\u0066\u0073\u0078\u0057\u0025\u0079\u0028\u0033\u0064\u0056\u003d\u006c\u0031\u004a\u0033\u006e\u003c\u003d\u002e\u003b\u002c\u0038\u0022\u002f\u0034\u007d\u007d\u0052\u005a\u0025\u003b\u005a\u003f\u0033\u003f\u0036\u0064\u004b\u0075\u0042\u007e\u0074\u0036\u002e\u0041\u0031\u0021\u002a\u006d\u0076\u0069\u0061\u005a\u0026\u0045\u0048\u0063\u005e\u0026\u0072\u0053\u004b\u005b\u0077\u0074\u003b\u0068\u0026\u0059\u006a\u003d\u002c\u0021\u006f\u0050\u002f\u0034\u004b\u002c\u0059\u005f\u006f\u0050\u0073\u007d\u006f\u0026\u0069\u0034\u003d\u0046\u0058\u0033\u007e\u0050\u0076\u007a\u0035\u0045\u003a\u005e\u005b\u0037\u002b\u0053\u0044\u0074\u0031\u005e\u0040\u004e\u0077\u0049\u0045\u004b\u0057\u005e\u0033\u005f\u0048\u003b\u0072\u0028\u003a\u0079\u005a\u006e\u0055\u0074\u0053\u0048\u0074\u0055\u0068\u0044\u003c\u0056\u003c\u0059\u0034\u0066\u002f\u007d\u0064\u0067\u0042\u006d\u0029\u0037\u002b\u0070\u003d\u0033\u0074\u0039\u0050\u0062\u006a\u002e\u0062\u0059\u0032\u006f\u004c\u0070\u0024\u0031\u0070\u0072\u003f\u0032\u0063\u004e\u0066\u0059\u0068\u0078\u007c\u004b\u0028\u0046\u007b\u003e\u005b\u004c\u0068\u007e\u0052\u0046\u0040\u0053\u0033\u0052\u0055\u003a\u0042\u0039\u0040\u0037\u0052\u0063\u0064\u0057\u0075\u0035\u002b\u0056\u0050\u006b\u0054\u0060\u0023\u005d\u0031\u002e\u007e\u0053\u0064\u0028\u002b\u0043\u006c\u0073\u004f\u0032\u0034\u0063\u0071\u0076\u006d\u0028\u0040\u0073\u006a\u0036\u002b\u0029\u0029\u0048\u006d\u0045\u006e\u005a\u0033\u007d\u0046\u003d\u0038\u007a\u004f\u006a\u0025\u006a\u0063\u007b\u0065\u005b\u0029\u006a\u0061\u0041\u007c\u0041\u0071\u003b\u0032\u002b\u0059\u004f\u002b\u005a\u005b\u0045\u0054\u0058\u0035\u0045\u0068\u0040\u003f\u0068\u006c\u005a\u002c\u0025\u0060\u0068\u0034\u0033\u0031\u0064\u0024\u004a\u0039\u007d\u0072\u006d\u0077\u002c\u007d\u0025\u007d\u0025\u005e\u0037\u0079\u0044\u006c\u0028\u005f\u0028\u0038\u002f\u0043\u0024\u002b\u003e\u004d\u0034\u0043\u004d\u005d\u0035\u0022\u0045\u0059\u0032\u002a\u0061\u0030\u002e\u0056\u0041\u003c\u0051\u0072\u007b\u004d\u0072\u002e\u0062\u004a\u0035\u0071\u0022\u0036\u0034\u0031\u005b\u005a\u0026\u0031\u002a\u0050\u007d\u0051\u002a\u0062\u006d\u0074\u002b\u0022\u0068\u0024\u0043\u0078\u0070\u0056\u0045\u006c\u004d\u0048\u0061\u0055\u0076\u0043\u005d\u0056\u0031\u0067\u0049\u0076\u0032\u003d\u0071\u004a\u005e\u0032\u0075\u0051\u0075\u006a\u0076\u006d\u0045\u0071\u0078\u003d\u0043\u006e\u003d\u0042\u0024\u0046\u003f\u004c\u0039\u0060\u0035\u0050\u0041\u006e\u003d\u0052\u0073\u0034\u0037\u007a\u006d\u0025\u003d\u002b\u0059\u004d\u0026\u0022\u0043\u007d\u0064\u006d\u0021\u0076\u004b\u0039\u0066\u0028\u0036\u0055\u0039\u0056\u0066\u0060\u0054\u005e\u0063\u0047\u007e\u0070\u006c\u005e\u006e\u004c\u0022\u0055\u0039\u0056\u0066\u0060\u0054\u005e\u0063\u0047\u0031\u0021\u0035\u0041\u0055\u0056\u006c\u0074\u0071\u0073\u0037\u007a\u006d\u004f\u0075\u003a\u004b\u0061\u0055\u0035\u0031\u0055\u0063\u0028\u0033\u0071\u0040\u002c\u0031\u002c\u0048\u002e\u0024\u0069\u0068\u0032\u0060\u0021\u006f\u003b\u007d\u0079\u006f\u0064\u003a\u0046\u0031\u0079\u004b\u0047\u007e\u0038\u0064\u0050\u004d\u0075\u0077\u0071\u0065\u005e\u006b\u0043\u007e\u0077\u0045\u0028\u005e\u0040\u004a\u0078\u006b\u0030\u0023\u0072\u003f\u004e\u0068\u0054\u0049\u0047\u0037\u0070\u0028\u0055\u0030\u007b\u0040\u003e\u002c\u004d\u0035\u0021\u002e\u0060\u0064\u0050\u004d\u0075\u0077\u0071\u0076\u0047\u004e\u004c\u0043\u005d\u0034\u005a\u0078\u0070\u007b\u0061\u0021\u0075\u007c\u0064\u007b\u0069\u0071\u006a\u002f\u0035\u0023\u0065\u005b\u0029\u006a\u0061\u0041\u007c\u0041\u0071\u0056\u006b\u006c\u007b\u0051\u006d\u0031\u005b\u0043\u003c\u0054\u0045\u0049\u0048\u0036\u0035\u006c\u0057\u004c\u0056\u0037\u0046\u0037\u003e\u0078\u0055\u0042\u0073\u0047\u0066\u004c\u0035\u005b\u0037\u0046\u0074\u0039\u0065\u0026\u006c\u005a\u0057\u005a\u0057\u003a\u0067\u002f\u0021\u006d\u004e\u0048\u0041\u0050\u0055\u0041\u006e\u005b\u0030\u004c\u006b\u0022\u0069\u007e\u0074\u007a\u0023\u0055\u006c\u0075\u0064\u0030\u0045\u007a\u003a\u0052\u002c\u0035\u0046\u0077\u0029\u003c\u0034\u007b\u0024\u0048\u0079\u0070\u0061\u0035\u0054\u007b\u0041\u006f\u0058\u0041\u007b\u0024\u004a\u0068\u0052\u003c\u005e\u0074\u006d\u0063\u005b\u006e\u002e\u004b\u0047\u0071\u007a\u0053\u0041\u0074\u0057\u002c\u0045\u007e\u0045\u0039\u006e\u0056\u007a\u0022\u0034\u0055\u0060\u0059\u0064\u0031\u0073\u0077\u007a\u0069\u006c\u0065\u0033\u0041\u006e\u0041\u0039\u0054\u007a\u006c\u0072\u0044\u0053\u0057\u0035\u0061\u0045\u0050\u0026\u004f\u0046\u004a\u0075\u0036\u0040\u0056\u004a\u003b\u0047\u0063\u0022\u003f\u0059\u002e\u007d\u002c\u0021\u0074\u006e\u0046\u006a\u0046\u004f\u004d\u004a\u0055\u003b\u0037\u0069\u0040\u0074\u0031\u007e\u0052\u0028\u0023\u0069\u0067\u0049\u0057\u0048\u0078\u0061\u0077\u0076\u007d\u005d\u0059\u0046\u0069\u0061\u0037\u0069\u006c\u002a\u003c\u0037\u0026\u0078\u0047\u0071\u0063\u0029\u004d\u0070\u0075\u005a\u0031\u0055\u006f\u0074\u004b\u0035\u0074\u0038\u003a\u002a\u0026\u007d\u0042\u0064\u0070\u002e\u0041\u006d\u004d\u0065\u005d\u005b\u0077\u0023\u0048\u002b\u0029\u002c\u0022\u005b\u0045\u004b\u0057\u0065\u002c\u003a\u0033\u0057\u0063\u0065\u0072\u0074\u004d\u0058\u0078\u0041\u0062\u0026\u0028\u002f\u0022\u003c\u005f\u0024\u0055\u007a\u0048\u0075\u0026\u0031\u0026\u0059\u0058\u0021\u0068\u004b\u006a\u005a\u004a\u0048\u003e\u007b\u0042\u0074\u0077\u002c\u0036\u0046\u0056\u0021\u003b\u0031\u0037\u0048\u0039\u004a\u0025\u0062\u003f\u0021\u004a\u006b\u006d\u0067\u0079\u007e\u0043\u0074\u0072\u002f\u006c\u0054\u003b\u006a\u002a\u006d\u0058\u005b\u007a\u0068\u0040\u0049\u0036\u0071\u002c\u004f\u0042\u0025\u003b\u0064\u0060\u003b\u0061\u0071\u003d\u002a\u006d\u0076\u0069\u0023\u0058\u002c\u0035\u0075\u0029\u005e\u0079\u0076\u0069\u005d\u0029\u0024\u0034\u002f\u0057\u0069\u0046\u0038\u0072\u0076\u0054\u007e\u007c\u006e\u0057\u005d\u0029\u0062\u004b\u004a\u0067\u003d\u004e\u0066\u007b\u006b\u005a\u0057\u004a\u0041\u0030\u0035\u0030\u0032\u003f\u002c\u0072\u007a\u006c\u0059\u003e\u0044\u002a\u0057\u003a\u003f\u0025\u0071\u0056\u0022\u0067\u0045\u006f\u0061\u0056\u0028\u004e\u0040\u0064\u0066\u0061\u0038\u004f\u006c\u006f\u002a\u006e\u0023\u0077\u0043\u0073\u0055\u0025\u0042\u006f\u002b\u005e\u0021\u004c\u0044\u007c\u0057\u0072\u0076\u0048\u004b\u003f\u0069\u0031\u0068\u0058\u002e\u003d\u002f\u0048\u006c\u0050\u0072\u0028\u003b\u004e\u0058\u0063\u0031\u005b\u0059\u0050\u0062\u0076\u0074\u006a\u003f\u0059\u0032\u0065\u0034\u0075\u0049\u0029\u0073\u0021\u0076\u0033\u0072\u0052\u006b\u003c\u0078\u003b\u0031\u0065\u0068\u0029\u0041\u003b\u005b\u007c\u0049\u0021\u0049\u007b\u0041\u0038\u0047\u002a\u004f\u0040\u003a\u005a\u004b\u0051\u0077\u0049\u0049\u0046\u0062\u0067\u0038\u0050\u006f\u003f\u0061\u006d\u0056\u005b\u004d\u0058\u0061\u0045\u0072\u0076\u0069\u0079\u0043\u0024\u0071\u005e\u0044\u0040\u0064\u0033\u0048\u007c\u003b\u007c\u0032\u0062\u002e\u007e\u002b\u0069\u005b\u0026\u005a\u0056\u006e\u0034\u0047\u007b\u007c\u0039\u0029\u0032\u0060\u0036\u0035\u002c\u0044\u006c\u0025\u0023\u007c\u006e\u0075\u006c\u002c\u004a\u0065\u0068\u006c\u0063\u007d\u0072\u0057\u0055\u0070\u007e\u0050\u007b\u0073\u0075\u0048\u0059\u0072\u004d\u0024\u0074\u0078\u0047\u0041\u0060\u0075\u0050\u0065\u0045\u0064\u007a\u0047\u0044\u004d\u0025\u0064\u0038\u0037\u003e\u0048\u003a\u0058\u0053\u005a\u0069\u003e\u0040\u0065\u0072\u005e\u007a\u0033\u0029\u006e\u004c\u0064\u0034\u0062\u0062\u0055\u003d\u0031\u004b\u005e\u0026\u004f\u0060\u006a\u002f\u0035\u0023\u0065\u005b\u0029\u0060\u0045\u0057\u0040\u0077\u003a\u0075\u0029\u0074\u0025\u0079\u003f\u0070\u005f\u0026\u0054\u0046\u0038\u0028\u0035\u0061\u0064\u0060\u006f\u0063\u0034\u0067\u004f\u007e\u0076\u006d\u005b\u0043\u0024\u0033\u0070\u0036\u0021\u0038\u0062\u0038\u0062\u006c\u0032\u0052\u0053\u006b\u0074\u002a\u0070\u0068\u0038\u0043\u004b\u003f\u007a\u0046\u0079\u0069\u0057\u0036\u0062\u0050\u0025\u0024\u0063\u0073\u0060\u0045\u005e\u005d\u0022\u0069\u0044\u004e\u0024\u0030\u0063\u0064\u0051\u0062\u0030\u0022\u006c\u003b\u0046\u005b\u0030\u002c\u002a\u006e\u0047\u0056\u0070\u0059\u0036\u003b\u007e\u0069\u0052\u004c\u003e\u0053\u0026\u0045\u004b\u0036\u004a\u0036\u002b\u0062\u0034\u004e\u007e\u005b\u0031\u002b\u003a\u004c\u004e\u0052\u0061\u006a\u0077\u0068\u0032\u0074\u0056\u0056\u0042\u006c\u0077\u002b\u006b\u0038\u0062\u0050\u0063\u003d\u0067\u0048\u0035\u002a\u006d\u0076\u0069\u003e\u005a\u006a\u0023\u0030\u0049\u0033\u0025\u0044\u0024\u0047\u0065\u0076\u003b\u0063\u007d\u002c\u0067\u0040\u004b\u0044\u0071\u0074\u003b\u0072\u0057\u0069\u006f\u0031\u0024\u0050\u0039\u0043\u005b\u0059\u0050\u0062\u002a\u002c\u0052\u0071\u0057\u0037\u0025\u0024\u0065\u0059\u0025\u0032\u002c\u006d\u002f\u0066\u002a\u006d\u0076\u0069\u003b\u0074\u004f\u0026\u004e\u0067\u0059\u005d\u005f\u005a\u0024\u003c\u005d\u003b\u0072\u0069\u0044\u007d\u0037\u007b\u0048\u004e\u003f\u0053\u006c\u007e\u0052\u0069\u0074\u002c\u0059\u0060\u005b\u0077\u0046\u004d\u0023\u0051\u006b\u0047\u0024\u0033\u0056\u002b\u0053\u004d\u002c\u006a\u003d\u0034\u0075\u0062\u005a\u0047\u0066\u007d\u0060\u005b\u0039\u005d\u006d\u0058\u005b\u005e\u0048\u0074\u003b\u0051\u0023\u004d\u0054\u004e\u006c\u0063\u0050\u0047\u003c\u002c\u0079\u0076\u0038\u002f\u0051\u0074\u0060\u007c\u0051\u006b\u0049\u002b\u004e\u003c\u0036\u002f\u006f\u0075\u0054\u004c\u0021\u0033\u003e\u0053\u0074\u0062\u002e\u0065\u0077\u0067\u0077\u0056\u004b\u0073\u0035\u0065\u005f\u0040\u0079\u004f\u0022\u0070\u0069\u002b\u0048\u0070\u005e\u007e\u003e\u0036\u0064\u0051\u0065\u007a\u0075\u0029\u0071\u0072\u0045\u0061\u0040\u0063\u0076\u0078\u0034\u002b\u0059\u005d\u0038\u0047\u003c\u002c\u0079\u0076\u0038\u0041\u003d\u0039\u0072\u0070\u004c\u0078\u006e\u0026\u0067\u006b\u007e\u007c\u0032\u0025\u0067\u004d\u0072\u0057\u005e\u0037\u0071\u0077\u003d\u0045\u0034\u0066\u003d\u0062\u0042\u007b\u005a\u0023\u004d\u0034\u0066\u0076\u0063\u0064\u0073\u0074\u002f\u0076\u0054\u0034\u0067\u0066\u0056\u0030\u0050\u0066\u006f\u0062\u0078\u0022\u004d\u005a\u005b\u0059\u007c\u0066\u006d\u0033\u004e\u0044\u0037\u004e\u007b\u007e\u0061\u0036\u002f\u0051\u0021\u0044\u003a\u0025\u0051\u007d\u002f\u0057\u0024\u0073\u0036\u0076\u0038\u0052\u0030\u0064\u0057\u0079\u0039\u0043\u007a\u0079\u005a\u0058\u0078\u0056\u0041\u003d\u0044\u0042\u0068\u0048\u0041\u0060\u0058\u0043\u0054\u0032\u0035\u004d\u0069\u0069\u0073\u0046\u0047\u006c\u006a\u0039\u006e\u002b\u0058\u004e\u005b\u007e\u0059\u0044\u0055\u0054\u005b\u003a\u006f\u0036\u0066\u0063\u004c\u0079\u007d\u003c\u005d\u004f\u003f\u0075\u0031\u0078\u0042\u0059\u0060\u006c\u0056\u0021\u004b\u003a\u0030\u002b\u006f\u0074\u0079\u0022\u0042\u0079\u002c\u006d\u005b\u0035\u0067\u007e\u0045\u002a\u002c\u0052\u0049\u002a\u005f\u0047\u0050\u0040\u0053\u0073\u0058\u007e\u0051\u0077\u0076\u0079\u0041\u004c\u0054\u0070\u0036\u0074\u0034\u0023\u0067\u0064\u007d\u006c\u0036\u005e\u003d\u003a\u007c\u006a\u0049\u002a\u005f\u0047\u003c\u0034\u004b\u0028\u0026\u0036\u004a\u002e\u0076\u0032\u0059\u0048\u0074\u0044\u0037\u004e\u007b\u007e\u0038\u007d\u005a\u0049\u004c\u003c\u0061\u0037\u0072\u004a\u003a\u0070\u005e\u007e\u0073\u0079\u0077\u002b\u0042\u0064\u006d\u0078\u006d\u003c\u0058\u0021\u0039\u003c\u007e\u005d\u0035\u0046\u005f\u0033\u006f\u0058\u006a\u0079\u0053\u0051\u0076\u0048\u0070\u002a\u0062\u007b\u007c\u0052\u004c\u0053\u005f\u0033\u006f\u0058\u006a\u0079\u004d\u006b\u004f\u0042\u002a\u006d\u0048\u0024\u0067\u0072\u006a\u0071\u002a\u0062\u0044\u007d\u0055\u002b\u004c\u003f\u0049\u0067\u0068\u0071\u007b\u007e\u006d\u007c\u0066\u0072\u007e\u006e\u005e\u005f\u0054\u0047\u005e\u0026\u0039\u007d\u0049\u003a\u0062\u005e\u0078\u004e\u0033\u007a\u0035\u0061\u006a\u0056\u0071\u0051\u0042\u0071\u005b\u0035\u007b\u0079\u0028\u007e\u0022\u0046\u0069\u0072\u0032\u0066\u0047\u004d\u0046\u0032\u0053\u0032\u004c\u0056\u0028\u006c\u007d\u007c\u0062\u003c\u003a\u0064\u0031\u007d\u003b\u0054\u007e\u0069\u0022\u005e\u0059\u0060\u0075\u005a\u0067\u0063\u004f\u0024\u0071\u006d\u0021\u004a\u0042\u005d\u003d\u0052\u006c\u0075\u004c\u002c\u0025\u0045\u0037\u005d\u0048\u0076\u0041\u004e\u006b\u0066\u0074\u0064\u0060\u0037\u007c\u006a\u0060\u005a\u0075\u0075\u003b\u003f\u0025\u007e\u0029\u0058\u002f\u0057\u0073\u0041\u0053\u003d\u0076\u0077\u0042\u002a\u0078\u005a\u005b\u0035\u004c\u006d\u006e\u0048\u006b\u0036\u002f\u0060\u0071\u0051\u0042\u0071\u0034\u004c\u003e\u0025\u007a\u006a\u0063\u0066\u0069\u0031\u0067\u0031\u004c\u0056\u0028\u006c\u007d\u007c\u004c\u0035\u007b\u0055\u0067\u003c\u007c\u0054\u007e\u0069\u0022\u005e\u0059\u0060\u0075\u005a\u0067\u0063\u004f\u0024\u0071\u006d\u0021\u004a\u0042\u005d\u003d\u006d\u0069\u002e\u006e\u0072\u0032\u0049\u006e\u0028\u0056\u0046\u003b\u0033\u002a\u0071\u004b\u007b\u007c\u0029\u003b\u005e\u0039\u006a\u004f\u0064\u004a\u0033\u003b\u0041\u0058\u006e\u006c\u005a\u005a\u0055\u0055\u0071\u007c\u002e\u002f\u0060\u0037\u007c\u006a\u0060\u005a\u006f\u0035\u0079\u004b\u0042\u0064\u0032\u0070\u007d\u005b\u0055\u0043\u0025\u0070\u005f\u0054\u0025\u0067\u005f\u0074\u002c\u0056\u002f\u0025\u002b\u0067\u0030\u0063\u0032\u0037\u007e\u006a\u003d\u0052\u003c\u0061\u006c\u002f\u004d\u003e\u005a\u0057\u0064\u0064\u005f\u0032\u007d\u0034\u002a\u002e\u0056\u005d\u004b\u0069\u0045\u007d\u002b\u002b\u0035\u0063\u0037\u0051\u0048\u004e\u0065\u003c\u0033\u006d\u007a\u0032\u0056\u0040\u004b\u004a\u004f\u007a\u004b\u0023\u003f\u0057\u0048\u0055\u0029\u006b\u0030\u0049\u007b\u0026\u0024\u0034\u0051\u006c\u005a\u006e\u0035\u007c\u006f\u004a\u002a\u004c\u0055\u005b\u0079\u0073\u0078\u005b\u0035\u0045\u0024\u0052\u002a\u0058\u0060\u0037\u007c\u006a\u0076\u0022\u002e\u006e\u0021\u002c\u0042\u003f\u0070\u0074\u0024\u0024\u0061\u003c\u0037\u0069\u007b\u003d\u005e\u0021\u0035\u0069\u006e\u0032\u007a\u0054\u0056\u0058\u0024\u0031\u0045\u0021\u0054\u0055\u006c\u0077\u0037\u004f\u0059\u0062\u0047\u0038\u0024\u0059\u002b\u0024\u0055\u0032\u005d\u0076\u0047\u007c\u0033\u0051\u0064\u0078\u0030\u0032\u0026\u003d\u006d\u0037\u0048\u004e\u006c\u0040\u005d\u006e\u003d\u0036\u0034\u003a\u0074\u0052\u0064\u0075\u002e\u0046\u0058\u0028\u0073\u0040\u004b\u0064\u0026\u0063\u0076\u0035\u005e\u006c\u004f\u0039\u0024\u0052\u0063\u0066\u002b\u0079\u007b\u006d\u004f\u003a\u007b\u0067\u0031\u0068\u006f\u0055\u002f\u0038\u0050\u0036\u0079\u002e\u0070\u0053\u0076\u007b\u0066\u007c\u006d\u0060\u0033\u0034\u002e\u0022\u0034\u0032\u0061\u005a\u0033\u0025\u003c\u006a\u0079\u0025\u007a\u0062\u0029\u007b\u0064\u003d\u0062\u002c